النمط الموصى به لتفادي تسريب الـ ViewBinding في الـ Fragments:
```kotlin
// ❌ كود خاطئ: يسرب الـ View Hierarchy عندما يذهب الـ Fragment إلى الـ BackStack:
class LeakyFragment : Fragment(R.layout.fragment_detail) {
    private lateinit var binding: FragmentDetailBinding // لن يتم تصفيرها في onDestroyView!

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        binding = FragmentDetailBinding.bind(view)
    }
}

// ✅ كود قياسي وآمن هندسياً: تصفير المرجع صراحة في onDestroyView:
class SafeFragment : Fragment(R.layout.fragment_detail) {
    private var _binding: FragmentDetailBinding? = null
    private val binding get() = _binding!! // صالح للاستخدام فقط بين onCreateView و onDestroyView

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        _binding = FragmentDetailBinding.bind(view)
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null // تحرير شجرة الواجهة للسماح للـ GC بجمعها فوراً!
    }
}
```

أمثلة شائعة للتسريبات وكيفية معالجتها بدقة:
```kotlin
// ❌ أمثلة شائعة للتسريب:
class LeakyActivity : AppCompatActivity() {
    private val handler = Handler(Looper.getMainLooper()) // كائن داخلي يمسك النشاط

    override fun onStart() {
        super.onStart()
        // 1. تسريب Handler: مهمة مؤجلة تبقى في MessageQueue:
        handler.postDelayed({ showPromotionDialog() }, 120_000)

        // 2. تسريب Listener: تسجيل في Singleton بدون إلغاء التسجيل:
        AuthManager.registerListener { onAuthStatusChanged(it) }
    }
}

// ✅ الكود النظيف المحمي من التسريب:
class SafeActivity : AppCompatActivity() {
    private val handler = Handler(Looper.getMainLooper())
    private val authListener: (Boolean) -> Unit = { onAuthStatusChanged(it) }

    override fun onStart() {
        super.onStart()
        AuthManager.registerListener(authListener)
    }

    override fun onStop() {
        super.onStop()
        // إلغاء المهام المؤجلة وإلغاء تسجيل الملاحظين فوراً:
        handler.removeCallbacksAndMessages(null) // مسح الـ MessageQueue
        AuthManager.unregisterListener(authListener) // تحرير مرجع النشاط
    }
}
```

